section.sourcecode:
id-shake128 OBJECT IDENTIFIER ::= { joint-iso-itu-t(2) 
     country(16) us(840) organization(1) gov(101) csor(3) 
     nistAlgorithm(4) 2 11 }

id-shake256 OBJECT IDENTIFIER ::= { joint-iso-itu-t(2) 
     country(16) us(840) organization(1) gov(101) csor(3) 
     nistAlgorithm(4) 2 12 }

id-RSASSA-PSS-SHAKE128  OBJECT IDENTIFIER  ::=  { iso(1) 
          identified-organization(3) dod(6) internet(1) 
          security(5) mechanisms(5) pkix(7) algorithms(6) 30 }

id-RSASSA-PSS-SHAKE256  OBJECT IDENTIFIER  ::=  { iso(1) 
          identified-organization(3) dod(6) internet(1) 
          security(5) mechanisms(5) pkix(7) algorithms(6) 31 }

id-KmacWithSHAKE128 OBJECT IDENTIFIER ::= { joint-iso-itu-t(2) 
    country(16) us(840) organization(1) gov(101) csor(3) 
    nistAlgorithm(4) 2 19 }

id-KmacWithSHAKE256 OBJECT IDENTIFIER ::= { joint-iso-itu-t(2) 
    country(16) us(840) organization(1) gov(101) csor(3) 
    nistAlgorithm(4) 2 20 }

CMSAlgsForSHAKE-2019 { iso(1) member-body(2) us(840) rsadsi(113549) pkcs(1) pkcs-9(9) smime(16) modules(0) id-mod-cms-shakes-2019(70) }
DEFINITIONS EXPLICIT TAGS ::=
BEGIN
-- EXPORTS ALL;
IMPORTS
DIGEST-ALGORITHM, MAC-ALGORITHM, SMIME-CAPS FROM AlgorithmInformation-2009 { iso(1) identified-organization(3) dod(6) internet(1) security(5) mechanisms(5) pkix(7) id-mod(0) id-mod-algorithmInformation-02(58) }
RSAPublicKey, rsaEncryption, id-ecPublicKey FROM PKIXAlgs-2009 { iso(1) identified-organization(3) dod(6) internet(1) security(5) mechanisms(5) pkix(7) id-mod(0) id-mod-pkix1-algorithms2008-02(56) }
sa-rsassapssWithSHAKE128, sa-rsassapssWithSHAKE256, sa-ecdsaWithSHAKE128, sa-ecdsaWithSHAKE256 FROM PKIXAlgsForSHAKE-2019 { iso(1) identified-organization(3) dod(6) internet(1) security(5) mechanisms(5) pkix(7) id-mod(0) id-mod-pkix1-shakes-2019(94) } ;
-- CMSのSignedData、SignerInfo、DigestedData、 -- AuthenticatedDataのdigestAlgorithmフィールドで -- 使用されるメッセージダイジェストアルゴリズム（mda-） -- -- これは[RFC5652]のMessageAuthAlgsと -- [RFC5753]のMessageDigestAlgsを拡張します -- -- MessageDigestAlgs DIGEST-ALGORITHM ::= { -- mda-shake128 | -- mda-shake256, -- ... -- }
-- -- 一方向ハッシュ関数 -- SHAKE128 mda-shake128 DIGEST-ALGORITHM ::= { IDENTIFIER id-shake128 -- 出力長は32バイト。 } id-shake128 OBJECT IDENTIFIER ::= { joint-iso-itu-t(2) country(16) us(840) organization(1) gov(101) csor(3) nistAlgorithm(4) hashAlgs(2) 11 }
-- SHAKE256 mda-shake256 DIGEST-ALGORITHM ::= { IDENTIFIER id-shake256 -- 出力長は64バイト。 } id-shake256 OBJECT IDENTIFIER ::= { joint-iso-itu-t(2) country(16) us(840) organization(1) gov(101) csor(3) nistAlgorithm(4) hashAlgs(2) 12 }
-- -- CMSのOriginatorPublicKeyのalgorithm属性に置かれる -- 公開鍵アルゴリズム識別子。 -- および、CMSの署名データコンテンツタイプと副署名属性の -- SignerInfoのsignatureAlgorithmフィールドで使用される -- 署名識別子。 -- -- 参考のため、RFC 5280から引用： -- rsaEncryption OBJECT IDENTIFIER ::= { pkcs-1 1 } -- rsaEncryptionアルゴリズム識別子を公開鍵に使用する場合、 -- AlgorithmIdentifierのparametersフィールドはNULLを -- 含まなければなりません（MUST）。 -- id-RSASSA-PSS-SHAKE128 OBJECT IDENTIFIER ::= { iso(1) identified-organization(3) dod(6) internet(1) security(5) mechanisms(5) pkix(7) algorithms(6) 30 }
id-RSASSA-PSS-SHAKE256 OBJECT IDENTIFIER ::= { iso(1) identified-organization(3) dod(6) internet(1) security(5) mechanisms(5) pkix(7) algorithms(6) 31 }
-- CMSでid-RSASSA-PSS-*アルゴリズム識別子を公開鍵または -- 署名に使用する場合、AlgorithmIdentifierのparameters -- フィールドは存在しないようにしなければなりません（MUST）。 -- RSASSA-PSSで使用するメッセージダイジェストアルゴリズムは、 -- それぞれ出力長32バイトのSHAKE128または出力長64バイトの -- SHAKE256でなければなりません（MUST）。マスク生成関数は、 -- それぞれ出力長(8*ceil((n-1)/8) - 264)ビットのSHAKE128 -- または出力長(8*ceil((n-1)/8) - 520)ビットのSHAKE256で -- なければなりません（MUST）。ここで、nはビット単位の -- RSAモジュラスです。RSASSA-PSSのsaltLengthは、それぞれ -- 32バイトまたは64バイトでなければなりません（MUST）。 -- trailerFieldは1でなければなりません（MUST）。これは -- 16進数値0xBCのトレーラーフィールドを表します。 -- OriginatorPublicKeyのAlgorithmIdentifierとして -- id-RSASSA-PSS-*とrsaEncryptionのどちらを使用する場合でも、 -- RSA公開鍵はRSAPublicKey型を使用してエンコード -- しなければなりません（MUST）。
-- 参考のため、RFC 4055から引用： -- RSAPublicKey ::= SEQUENCE { -- modulus INTEGER, -- -- n -- publicExponent INTEGER } -- -- e
id-ecdsa-with-shake128 OBJECT IDENTIFIER ::= { iso(1) identified-organization(3) dod(6) internet(1) security(5) mechanisms(5) pkix(7) algorithms(6) 32 }
id-ecdsa-with-shake256 OBJECT IDENTIFIER ::= { iso(1) identified-organization(3) dod(6) internet(1) security(5) mechanisms(5) pkix(7) algorithms(6) 33 }
-- CMSでid-ecdsa-with-shake*アルゴリズム識別子を使用する -- 場合、AlgorithmIdentifierのparametersフィールドは存在 -- しないようにしなければならず（MUST）、署名アルゴリズムは -- 決定論的ECDSA [RFC6979]であるべきです。メッセージ -- ダイジェストは、それぞれ出力長32バイトのSHAKE128または -- 出力長64バイトのSHAKE256でなければなりません（MUST）。 -- どちらの場合も、ECDSA公開鍵はid-ecPublicKey型を使用して -- エンコードしなければなりません（MUST）。
-- 参考のため、RFC 5480から引用： -- id-ecPublicKey OBJECT IDENTIFIER ::= { -- iso(1) member-body(2) us(840) ansi-X9-62(10045) keyType(2) 1 } -- id-ecPublicKeyのパラメーターは存在しても存在しなくても -- よく、次のように定義されます： -- ECParameters ::= CHOICE { -- namedCurve OBJECT IDENTIFIER -- -- -- implicitCurve NULL -- -- -- specifiedCurve SpecifiedECDomain -- }
-- これは[RFC5912]のSignatureAlgsを拡張します -- -- SignatureAlgs SIGNATURE-ALGORITHM ::= { -- sa-rsassapssWithSHAKE128 | -- sa-rsassapssWithSHAKE256 | -- sa-ecdsaWithSHAKE128 | -- sa-ecdsaWithSHAKE256, -- ... -- }
-- これは[RFC5652]と[RFC6268]のMessageAuthAlgsを拡張します -- -- CMSのAuthenticatedDataのmacAlgorithmで使用される -- メッセージ認証（maca-）アルゴリズム -- MessageAuthAlgs MAC-ALGORITHM ::= { maca-KMACwithSHAKE128 | maca-KMACwithSHAKE256, ... }
-- これは[RFC5911]のSMimeCapsを拡張します -- SMimeCaps SMIME-CAPS ::= { -- sa-rsassapssWithSHAKE128.&smimeCaps | -- sa-rsassapssWithSHAKE256.&smimeCaps | -- sa-ecdsaWithSHAKE128.&smimeCaps | -- sa-ecdsaWithSHAKE256.&smimeCaps, maca-KMACwithSHAKE128.&smimeCaps | maca-KMACwithSHAKE256.&smimeCaps, ... }
-- -- SHAKE128を使用するKMAC maca-KMACwithSHAKE128 MAC-ALGORITHM ::= { IDENTIFIER id-KMACWithSHAKE128 PARAMS TYPE KMACwithSHAKE128-params ARE optional -- KMACwithSHAKE128-paramsパラメーターが存在しない場合、 -- KMACで使用するSHAKE128の出力長は256ビットで、 -- カスタマイズ文字列は空文字列です。 IS-KEYED-MAC TRUE SMIME-CAPS {IDENTIFIED BY id-KMACWithSHAKE128} } id-KMACWithSHAKE128 OBJECT IDENTIFIER ::= { joint-iso-itu-t(2) country(16) us(840) organization(1) gov(101) csor(3) nistAlgorithm(4) hashAlgs(2) 19 } KMACwithSHAKE128-params ::= SEQUENCE { kMACOutputLength INTEGER DEFAULT 256, -- ビット単位の出力長 customizationString OCTET STRING DEFAULT ''H }
-- SHAKE256を使用するKMAC maca-KMACwithSHAKE256 MAC-ALGORITHM ::= { IDENTIFIER id-KMACWithSHAKE256 PARAMS TYPE KMACwithSHAKE256-params ARE optional -- KMACwithSHAKE256-paramsパラメーターが存在しない場合、 -- KMACで使用するSHAKE256の出力長は512ビットで、 -- カスタマイズ文字列は空文字列です。 IS-KEYED-MAC TRUE SMIME-CAPS {IDENTIFIED BY id-KMACWithSHAKE256} } id-KMACWithSHAKE256 OBJECT IDENTIFIER ::= { joint-iso-itu-t(2) country(16) us(840) organization(1) gov(101) csor(3) nistAlgorithm(4) hashAlgs(2) 20 } KMACwithSHAKE256-params ::= SEQUENCE { kMACOutputLength INTEGER DEFAULT 512, -- ビット単位の出力長 customizationString OCTET STRING DEFAULT ''H }
END
